AT=$(python3 -c "import json; print(json.load(open('/tmp/owner_at.json'))['accessToken'])")

echo "=== COMMIT chat.tsx change ==="
python3 << 'PYEOF'
import base64, gzip, json, urllib.request

with open('/tmp/owner_at.json') as f:
    at = json.load(f)['accessToken']

files_to_commit = [
    {
        'path': 'expo/app/ivx/chat.tsx',
        'content': open('/home/user/rork-app/expo/app/ivx/chat.tsx', 'rb').read(),
        'message': 'IVX Chat: remove remaining composer loading status messages (Recording/Transcribing/Reply-pending) and unused ActivityIndicator import per owner request'
    },
    {
        'path': 'expo/app.config.ts',
        'content': open('/home/user/rork-app/expo/app.config.ts', 'rb').read(),
        'message': 'IVX Chat: bump version to 1.4.31(63) buildMarker IVX_BUNDLE_2026_07_21_BUILD_63_CHAT_COMPOSER_LOADING_REMOVED'
    },
    {
        'path': 'expo/android/app/build.gradle',
        'content': open('/home/user/rork-app/expo/android/app/build.gradle', 'rb').read(),
        'message': 'IVX Chat: bump build.gradle to versionCode 63, versionName 1.4.31'
    }
]

for finfo in files_to_commit:
    compressed = gzip.compress(finfo['content'])
    encoded = base64.b64encode(compressed).decode('ascii')
    payload = {
        'action': 'github_commit_file',
        'input': {
            'path': finfo['path'],
            'content': encoded,
            'contentEncoding': 'gzip-base64',
            'message': finfo['message']
        },
        'confirm': True,
        'confirmText': 'CONFIRM_IVX_GITHUB_WRITE'
    }
    req = urllib.request.Request(
        'https://api.ivxholding.com/api/ivx/developer-deploy/action',
        data=json.dumps(payload).encode(),
        headers={
            'Authorization': f'Bearer {at}',
            'Content-Type': 'application/json'
        },
        method='POST'
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            resp = json.loads(r.read())
            print(f"PATH: {finfo['path']}")
            print(f"  OK: {resp.get('ok')}")
            print(f"  COMMIT: {resp.get('result', {}).get('commitSha', '?')[:12]}")
    except Exception as e:
        print(f"PATH: {finfo['path']}")
        print(f"  ERROR: {str(e)[:120]}")
PYEOF

